const dir=process.argv[2];
let fixture;
for (let i=0;i<100;i++){try{fixture=JSON.parse(await readFile(`${dir}/fixture.json`,'utf8'));break;}catch{await new Promise(resolve=>setTimeout(resolve,100));}}
assert.ok(fixture,'TLS fixture readiness');
const {origin,port,native_url}=fixture;
const browser=await chromium.launch({headless:true,args:[`--host-resolver-rules=MAP archive.example.com 127.0.0.1:${port}`,'--no-proxy-server']});
