const page=await context.newPage();const logs=[],errors=[],urls=[],secrets=[];
page.on('console',m=>logs.push(m.text()));page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>urls.push(r.url()));
page.on('response',async r=>{if(r.url().endsWith('/api/remote/login')&&r.ok()){try{const v=await r.json();if(v.challenge)secrets.push(v.challenge);if(v.csrf_token)secrets.push(v.csrf_token);}catch{}}});
await page.addInitScript(()=>{const original=window.fetch.bind(window);window.fetch=async(...args)=>{const response=await original(...args);if(window.delayedPath&&String(args[0])===window.delayedPath){window.delayedPath='';return await new Promise(resolve=>{window.releaseDelayed=()=>{const delayed=window.delayedStatus?new Response("",{status:window.delayedStatus}):response;window.delayedStatus=0;resolve(delayed);};});}return response;};});
