async function storageClean(){const v=await page.evaluate(()=>({local:Object.entries(localStorage),session:Object.entries(sessionStorage),url:location.href,history:history.state}));assert.deepEqual(v.local,[]);assert.deepEqual(v.session,[]);assert.equal(v.url,origin+'/');assert.equal(v.history,null);assert.ok(urls.every(u=>!u.includes('correct%20passphrase')&&!u.includes('challenge=')&&!u.includes('csrf=')));assert.ok(!logs.join(' ').includes('correct passphrase'));for(const secret of secrets){assert.ok(!urls.join(' ').includes(secret));assert.ok(!logs.join(' ').includes(secret));}}
