 await page.locator('#clients-open').click();await page.getByText('Synthetic private connection',{exact:true}).waitFor();assert.equal(await page.getByRole('button',{name:'Reveal remote token'}).count(),0);await page.locator('#clients-close').click();await page.locator('#settings-open').click();await page.locator('#settings-dialog').waitFor({state:'visible'});assert.equal(await page.locator('#delete-open').isVisible(),false);await page.locator('#settings-close').click();await page.locator('#connection-open').click();await page.locator('#pairing-code').waitFor({state:'visible'});assert.ok((await page.locator('#pairing-qr').getAttribute('src')).startsWith('blob:'));await page.locator('#connection-close').click();await page.screenshot({path:`${dir}/archive-390.png`,fullPage:true});
