 await page.waitForFunction(()=>!document.getElementById('remote-login-submit').disabled);await login();await page.locator('#workspace').waitFor({state:'visible'});await page.locator('#nav-archive').click();await page.locator('#search-query').fill('Synthetic new');await page.locator('#search-query').press('Enter');await page.locator('#search-results button').waitFor();await page.evaluate(()=>window.releaseDelayed());await page.waitForTimeout(100);assert.equal(await page.locator('#search-query').inputValue(),'Synthetic new');assert.equal(await page.locator('#search-results button').count(),1);
